import{_ as l,o as e,c as i,at as t}from"./chunks/framework.CY22Hent.js";const o="/assets/ruankao_2025-11-06_153617_176.BEGp9Ht3.png",h=JSON.parse('{"title":"软件设计师笔记12_软件系统分析与设计_精简考点","description":"","frontmatter":{"title":"软件设计师笔记12_软件系统分析与设计_精简考点","date":"2025-04-05T00:00:00.000Z","lastUpdated":"2025-11-06T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/软件设计师笔记12_软件系统分析与设计_精简考点.md","filePath":"blogs/软考/软件设计师笔记12_软件系统分析与设计_精简考点.md"}'),_={name:"blogs/软考/软件设计师笔记12_软件系统分析与设计_精简考点.md"};function r(p,a,n,s,u,d){return e(),i("div",null,[...a[0]||(a[0]=[t('<p>[toc]</p><h1 id="软件设计师笔记12-软件系统分析与设计-精简考点" tabindex="-1">软件设计师笔记12_软件系统分析与设计_精简考点 <a class="header-anchor" href="#软件设计师笔记12-软件系统分析与设计-精简考点" aria-label="Permalink to &quot;软件设计师笔记12_软件系统分析与设计_精简考点&quot;">​</a></h1><p><img src="'+o+'" alt="ruankao_2025-11-06_153617_176.png" loading="lazy"></p><h2 id="结构化分析与设计-⭐️" tabindex="-1">结构化分析与设计 ⭐️ <a class="header-anchor" href="#结构化分析与设计-⭐️" aria-label="Permalink to &quot;结构化分析与设计 ⭐️&quot;">​</a></h2><blockquote><p>结构化分析的核心对象</p></blockquote><ul><li>数据：实体对象的属性和关系</li><li>处理：对信息的加工和处理</li></ul><blockquote><p>结构化分析步骤</p></blockquote><p>① 确定系统边界，绘制系统环境图 → ② 绘制各层数据流图（自顶向下）→ ③ 定义数据字典 → ④ 定义加工（处理）说明 → ⑤ 将图、字典和加工组成分析模型。</p><blockquote><p>结构化分析的最终产出结果</p></blockquote><ul><li>数据流图：系统数据流的可视化表示。</li><li>数据字典：系统数据的属性和关系的详细描述。</li><li>加工处理说明：系统数据的加工和处理的详细说明。（如结构化英语、判定表、判定树）</li></ul><h3 id="数据流图-dfd-⭐️" tabindex="-1">数据流图 （DFD） ⭐️ <a class="header-anchor" href="#数据流图-dfd-⭐️" aria-label="Permalink to &quot;数据流图 （DFD） ⭐️&quot;">​</a></h3><p>数据流图（DFD）是面向数据流建模的工具。</p><blockquote><p>数据流图（DFD）的基本元素</p></blockquote><ul><li>外部实体：系统外部的实体，如用户、数据库、文件等。</li><li>数据流：系统内部的实体，如数据、信息等。</li><li>加工：系统内部的实体，如计算、转换、排序等。</li><li>数据存储：系统内部的实体，如数据库、文件等。</li></ul><h2 id="数据库分析与设计-⭐️" tabindex="-1">数据库分析与设计 ⭐️ <a class="header-anchor" href="#数据库分析与设计-⭐️" aria-label="Permalink to &quot;数据库分析与设计 ⭐️&quot;">​</a></h2><h3 id="数据库设计的策略" tabindex="-1">数据库设计的策略 <a class="header-anchor" href="#数据库设计的策略" aria-label="Permalink to &quot;数据库设计的策略&quot;">​</a></h3><p>数据库设计的一般策略有两种:自顶向下(Top Down)和自底向上(Bottom Up)。</p><ul><li>自顶向下：从整体到局部，先定义全局概念模型。</li><li>自底向上：从局部到整体，先定义局部概念模型。</li></ul><h3 id="数据库设计的步骤" tabindex="-1">数据库设计的步骤 <a class="header-anchor" href="#数据库设计的步骤" aria-label="Permalink to &quot;数据库设计的步骤&quot;">​</a></h3><p>数据库应用系统的生命周期分为六个阶段：</p><p>数据库规划 → 需求描述与分析 → 数据库设计与应用程序设计 → 实现 → 测试 → 运行与维护</p><p>其中：</p><ul><li>需求描述与分析是以用户的角度进行的。</li><li>应用程序设计包括事务设计和用户界面设计。</li><li>DDL（数据定义语言）用于建立数据库。</li></ul><h2 id="面向对象分析与设计-⭐️" tabindex="-1">面向对象分析与设计 ⭐️ <a class="header-anchor" href="#面向对象分析与设计-⭐️" aria-label="Permalink to &quot;面向对象分析与设计 ⭐️&quot;">​</a></h2><p>面向对象分析包括四个活动：建模系统功能 → 定义领域模型 → 定义交互行为和状态 → 定义设计类图</p><p>通过用例建模系统功能的步骤：</p><ul><li>①确定参与者；</li><li>②确定需求用例；</li><li>③构造用例模型；</li><li>④记录需求用例描述。</li></ul>',27)])])}const b=l(_,[["render",r]]);export{h as __pageData,b as default};
